Global External HTTP(S) Load Balancers.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(GlobalExternalHTTPSSLoadBalancers, "Global External HTTP(S) Load Balancers") {
    Component(AnycastIPFrontend, "Anycast IP Frontend", "HTTP/2, gRPC, TLS 1.3", "Terminates TLS 1.3 globally and handles incoming requests from web and mobile applications.")
    Component(CloudArmorSecurityPolicyEngine, "Cloud Armor Security Policy Engine", "Google Cloud Armor", "Mitigates DDoS attacks and enforces WAF and geo-access rules.")
    Component(URLMapRedirectComponent, "URL Map & Redirect Component", "GCP Global External HTTP(S) Load Balancer Routing", "Executes geo-routing policies and directs traffic to appropriate regional destinations or edge services.")
    Component(RegionSelectionEdgeService, "Region-Selection Edge Service", "Cloud Storage, Cloud CDN", "Routes ambiguous or unrouted requests to static edge assets and provides graceful edge fallbacks.")
}

Rel(AnycastIPFrontend, CloudArmorSecurityPolicyEngine, "Inspects incoming requests for security policies", "HTTPS / gRPC")
Rel(CloudArmorSecurityPolicyEngine, URLMapRedirectComponent, "Passes validated traffic for routing decisions", "")
Rel(URLMapRedirectComponent, RegionSelectionEdgeService, "Routes ambiguous or unrouted requests to static edge assets", "HTTPS")

@enduml

Media Relay / SFU Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Media Relay / SFU Container container

Container_Boundary("Media Relay / SFU Container", "Media Relay / SFU Container") {
    Component("Signaling_and_Room_Manager", "Signaling and Room Manager", "LiveKit / Go", "Handles WebRTC signaling, client connections, and room state management for video consultations.")
    Component("Media_Forwarding_Engine", "Media Forwarding Engine", "LiveKit / SFU", "Selective Forwarding Unit (SFU) that routes video and audio streams between participants with adaptive bitrate streaming.")
    Component("Encryption_and_Security_Handler", "Encryption and Security Handler", "DTLS 1.3 / SRTP", "Enforces end-to-end encryption for all real-time media streams.")
}

Rel("Signaling_and_Room_Manager", "Media_Forwarding_Engine", "Coordinates track publication and subscription", "")
Rel("Media_Forwarding_Engine", "Encryption_and_Security_Handler", "Encrypts and decrypts real-time media packets", "")

@enduml

Prescription & Interoperability Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(prescription_interoperability_service, "Prescription & Interoperability Service") {
    Component(Prescription_API_Controller, "Prescription API Controller", "Java/Spring Boot", "Forwards prescription requests, validates tokens, and processes incoming calls.")
    Component(FHIR_National_Mapping_Engine, "FHIR & National Mapping Engine", "Java with HAPI FHIR", "Validates payloads and standardizes US and international healthcare interoperability data structures.")
    Component(Pharmacy_Integration_Client, "Pharmacy Integration Client", "Java Spring WebClient", "Transmits e-prescriptions to local pharmacies and manages integration payloads.")
    Component(Prescription_Outbox_Retry_Processor, "Prescription Outbox & Retry Processor", "Java/Spring Boot, Resilience4j, Spring Cloud Stream", "Implements circuit breakers, retry logic, and forwards failed delivery events.")
}

Rel(Prescription_API_Controller, FHIR_National_Mapping_Engine, "Validates payload and passes data", "In-memory")
Rel(FHIR_National_Mapping_Engine, Pharmacy_Integration_Client, "Passes serialized payloads", "In-memory")
Rel(Pharmacy_Integration_Client, Prescription_Outbox_Retry_Processor, "Forwards failed delivery events", "In-memory / Event")

@enduml
